/* Contexto, diagnóstico operacional e pedidos com quantidades escolhidas. */
function quantity(){const value=Number($('quantity').value);return Number.isInteger(value)&&value>=1&&value<=1000?value:null}
function purchaseInfo(){let n=quantity(),free=cap('receiving')-s.stock.receiving,waiting=pending(),fits=n===null?0:Math.min(n,Math.max(0,free-waiting));$('purchaseInfo').textContent=`Caixa: $${s.cash.toFixed(2)} • Custo: $6/caixa\nRecebimento livre: ${free}/${cap('receiving')} • Depósito livre: ${cap('pallet')+cap('rack')-s.stock.pallet-s.stock.rack}/${cap('pallet')+cap('rack')} caixas.\n`+(n===null?'Informe um número inteiro de 1 a 1000.':`Total: $${(n*6).toFixed(2)} • Após a compra: $${(s.cash-n*6).toFixed(2)}.\nDescarga automática: até ${fits} deste pedido cabem; ${n-fits} aguardam espaço. ${waiting} caixas anteriores têm prioridade.`);$('purchaseInfo').style.whiteSpace='pre-line';$('buy').textContent=n===null?'Quantidade inválida':`Comprar ${n} caixa(s) • $${(n*6).toFixed(2)}`;$('buy').disabled=n===null||n*6>s.cash}
$('quantity').oninput=purchaseInfo;
$('buy').onclick=()=>{let n=quantity();if(n===null)return say('Informe quantidade inteira de 1 a 1000 caixas.',true);if(n*6>s.cash)return say('Caixa insuficiente para este pedido.',true);s.cash-=n*6;s.purchases+=n*6;s.purchased+=n;s.orders.push({total:n,received:0,pending:n});say(`Pedido de ${n} caixas criado por $${(n*6).toFixed(2)}. A descarga ocorre automaticamente no recebimento.`);purchaseInfo()};
function nearbyDoor(){return doors[s.room].find(d=>Math.hypot(s.player[0]-d.p[0],s.player[1]-d.p[1])<85)}
$('contextDoor').onclick=()=>{let d=nearbyDoor();if(!d)return say('Aproxime-se de uma porta.',true);let path=route(s.room,s.player,d.p);if(!path)return say('Caminho bloqueado.',true);playerPath=path;target=d.p;doorTarget=d};
function workerDescription(){const task=s.task;if(s.stock.worker){let p=places[s.dest],name=p[2];if(s.stock[s.dest]>=cap(s.dest))return `Aguardando espaço em ${name}. Mantém ${s.stock.worker} caixa em mãos; a atividade ${task} começa após a entrega.`;if(s.workerRoom===stationRoom(s.dest)&&!route(s.workerRoom,s.worker,[p[0],p[1]+90]))return 'Caminho bloqueado até '+name+'. Carga preservada.';return `Levando ${s.stock.worker} caixa para ${name}`+(s.workerRoom!==stationRoom(s.dest)?' • atravessando ambientes.':'.')}
if(task==='Parado')return 'Parado por sua ordem. Escolha uma atividade abaixo.';
let source,destination;if(task==='Transportar'){source='receiving';destination=s.stock.pallet<cap('pallet')?'pallet':'rack';if(!s.stock.receiving)return pending()?'Descarga automática aguardando espaço no recebimento.':'Aguardando mercadorias no recebimento.';if(s.stock[destination]>=cap(destination))return 'Depósito cheio: libere espaço no pallet ou na prateleira.'}else{source=s.stock.pallet?'pallet':'rack';destination='sales';if(s.stock.sales>=cap('sales'))return 'Expositor abastecido. Aguarda espaço e retoma sozinho.';if(!s.stock[source])return 'Sem mercadoria no depósito para repor o expositor.'}
let p=places[source];if(s.workerRoom===stationRoom(source)&&!route(s.workerRoom,s.worker,[p[0],p[1]+90]))return 'Caminho bloqueado até '+p[2]+'.';return 'Buscando caixas em '+p[2]+(s.workerRoom!==stationRoom(source)?' • atravessando ambientes.':'.')}
function contextualUI(){let k=near(),d=nearbyDoor(),cashier=atCheckout();$('contextDoor').hidden=!d;if(d)$('contextDoor').textContent=d.name;
$('take').hidden=!k;$('drop').hidden=!k;$('serve').hidden=!cashier;$('unload').hidden=true;
if(k){let free=cap(k)-s.stock[k],carryFree=cap('player')-s.stock.player;$('take').textContent=`Retirar de ${places[k][2]}`;$('drop').textContent=k==='sales'?'Repor expositor':`Depositar em ${places[k][2]}`;$('take').disabled=s.stock[k]===0||carryFree===0;$('drop').disabled=s.stock.player===0||free===0;$('contextHint').textContent=`${places[k][2]}: ${s.stock[k]}/${cap(k)} caixas • `+(free===0?'Destino cheio. ':`Cabem ${free}. `)+(s.stock.player?`Você carrega ${s.stock.player}.`:'Você está sem carga.')}else if(cashier){let first=queue()[0];$('contextHint').textContent=first?'Caixa • cliente '+first.id+' na frente da fila.':'Caixa • aguardando cliente.';$('serve').disabled=!first||first.serving||Math.hypot(first.pos[0]-QUEUE[0][0],first.pos[1]-QUEUE[0][1])>8}else $('contextHint').textContent=d?'Porta próxima • '+d.name:'Toque em uma porta, no expositor, no caixa ou em uma área de estoque para se aproximar.';
$('workerStatus').textContent=`Funcionário • ${s.task}\n${workerDescription()}`;$('workerStatus').style.whiteSpace='pre-line';purchaseInfo()}
const operationStep=step;step=function(dt){operationStep(dt);contextualUI()};
const operationRestore=$('restore').onclick;$('restore').onclick=()=>{operationRestore();contextualUI()};
contextualUI();
